#!/usr/bin/env python3
"""Generate native/hs_webrtc.h from implemented exports in hs_webrtc_bridge.cpp.

Parses every extern C function definition in the bridge and emits matching
C prototypes plus the frozen ABI-3-subset macros. The header is generated only;
do not hand-edit native/hs_webrtc.h.

Usage:
  python3 scripts/gen_header.py <bridge.cpp> <output.h>
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

HEADER = r"""/* hs_webrtc.h -- Helicoid E01 ABI-3 subset on Google WebRTC.
 *
 * GENERATED by scripts/gen_header.py from native/hs_webrtc_bridge.cpp
 * (implemented extern C exports only). Do not hand-edit;
 * re-run the generator after changing the bridge.
 *
 * Scope of this ABI (deliberately narrow):
 *   - explicit engine initialization and owned peer lifecycle
 *   - offer/answer + ICE negotiation
 *   - bounded data-channel product messages
 *   - channel-evidence: opaque verified-channel handle from the actual
 *     negotiated DTLS peer certificate (connected transport only)
 *   - drain/close with honest timeout
 *
 * A caller-provided SDP fingerprint string is NOT verified identity.
 * The verified-channel handle is engine-issued, bound to one peer generation,
 * invalidated on close / DTLS failure / certificate replacement, and cannot be
 * fabricated from caller identity data.
 *
 * Production capture / admission / media stay explicitly unavailable.
 *
 * Handle model: hs_engine*, hs_peer* and hs_verified_channel* are opaque
 * registry tokens cast to pointers. Never dereference them. Never forge them.
 * Released tokens are permanently retired; reuse is impossible by design.
 */
#ifndef HS_WEBRTC_H
#define HS_WEBRTC_H

#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/* --- ABI version --- */
#define HS_ABI_VERSION 3u

/* --- status codes --- */
#define HS_STATUS_OK 0u
#define HS_STATUS_INVALID 1u
#define HS_STATUS_NULL 2u
#define HS_STATUS_STATE 3u
#define HS_STATUS_PANIC 4u
#define HS_STATUS_EXHAUSTED 5u
#define HS_STATUS_UNAVAILABLE 6u
#define HS_STATUS_INTERNAL 7u
#define HS_STATUS_BOUNDS 8u
#define HS_STATUS_TIMEOUT 9u
#define HS_STATUS_HANDSHAKE 10u

/* --- capability bits (hs_engine_capabilities) --- */
#define HS_CAP_INITIALIZATION 0x1u
#define HS_CAP_NEGOTIATION 0x2u
#define HS_CAP_CHANNEL_EVIDENCE 0x4u
#define HS_CAP_DRAIN 0x8u
#define HS_CAP_CAPTURE 0x10u
#define HS_CAP_ADMISSION 0x20u
#define HS_CAP_MEDIA 0x40u

/* --- peer lifecycle states --- */
#define HS_PEER_STATE_NEW 0u
#define HS_PEER_STATE_CONNECTED 1u
#define HS_PEER_STATE_CHANNEL_OPEN 2u
#define HS_PEER_STATE_CLOSING 3u
#define HS_PEER_STATE_CLOSED 4u
#define HS_PEER_STATE_FAILED 5u

/* --- bounds (fail closed) --- */
#define HS_MAX_SDP_BYTES 65536u
#define HS_MAX_MSG_BYTES 4096u
#define HS_MAX_CERT_PEM_BYTES 8192u
#define HS_MAX_LABEL_BYTES 64u
#define HS_MAX_ICE_QUEUE 32u
#define HS_MAX_MSG_QUEUE 32u

/* Permitted bounded product data-channel label. Unexpected labels are closed. */
#define HS_PRODUCT_CHANNEL_LABEL "hs-product"

/* Opaque registry tokens. Never dereference; pass back to the engine only. */
typedef struct hs_engine hs_engine;
typedef struct hs_peer hs_peer;
typedef struct hs_verified_channel hs_verified_channel;

/* Export macro, three modes:
 *   HS_WEBRTC_STATIC  -> no dllimport/dllexport (static bridge + its harness)
 *   HS_WEBRTC_EXPORTS -> dllexport (building the shared library)
 *   neither           -> dllimport (consuming the shared library)
 * Chromium toolchain uses -fvisibility=hidden; MSVC/clang-cl needs __declspec.
 */
#if defined(_WIN32)
  #if defined(HS_WEBRTC_STATIC)
    #define HS_API
  #elif defined(HS_WEBRTC_EXPORTS)
    #define HS_API __declspec(dllexport)
  #else
    #define HS_API __declspec(dllimport)
  #endif
#elif defined(__GNUC__) || defined(__clang__)
  #define HS_API __attribute__((visibility("default")))
#else
  #define HS_API
#endif

"""

FOOTER = r"""
#ifdef __cplusplus
}
#endif

#endif /* HS_WEBRTC_H */
"""


def normalize_params(raw: str) -> str:
    parts = []
    for part in raw.split(","):
        part = " ".join(part.split())
        if part in ("void", ""):
            continue
        parts.append(part)
    if not parts:
        return "void"
    return ", ".join(parts)


def main() -> int:
    if len(sys.argv) != 3:
        print("usage: gen_header.py <bridge.cpp> <output.h>", file=sys.stderr)
        return 2
    src = Path(sys.argv[1]).read_text(encoding="utf-8")
    out_path = Path(sys.argv[2])

    start = src.find('extern "C" {')
    end = src.rfind("}  // extern \"C\"")
    if start < 0:
        raise SystemExit("no extern C open found")
    if end < 0:
        end = len(src)
    body = src[start:end]

    # Function definitions: return type, name, params, opening brace on same or next lines.
    func_re = re.compile(
        r"((?:const\s+)?[A-Za-z_][A-Za-z0-9_]*(?:\s*\*)?)\s+"
        r"(hs_[A-Za-z0-9_]+)\s*\(([^)]*)\)\s*\{",
        re.MULTILINE,
    )

    decls = []
    seen = set()
    for match in func_re.finditer(body):
        ret = " ".join(match.group(1).split())
        name = match.group(2)
        params = normalize_params(match.group(3))
        if name in seen:
            continue
        seen.add(name)
        decls.append(f"HS_API {ret} {name}({params});")

    if not decls:
        raise SystemExit("no hs_* exports found")

    text = HEADER + "\n".join(decls) + "\n" + FOOTER
    out_path.write_text(text, encoding="utf-8", newline="\n")
    print(f"generated {out_path} with {len(decls)} exports")
    for d in decls:
        print(" ", d)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
